solution.solution.cpp:
#include <map>
#include <set>
#include <utility>

class InputMap
{
public:
    void bind(int key, int action) { m_bindings.insert({ key, action }); }

    void update(const std::set<int>& keysDown)
    {
        m_previous = m_current;
        m_current.clear();
        for (const auto& [key, action] : m_bindings)
            if (keysDown.count(key)) m_current.insert(action);
    }

    bool held(int action) const { return m_current.count(action) > 0; }
    bool pressed(int action) const { return held(action) && !m_previous.count(action); }
    bool released(int action) const { return !held(action) && m_previous.count(action) > 0; }

private:
    std::set<std::pair<int, int>> m_bindings;     // (key, action)
    std::set<int> m_current;                      // actions down this frame
    std::set<int> m_previous;                     // actions down last frame
};

unitTests:
const int JUMP{ 1 }, LEFT{ 2 }, FIRE{ 3 };
TEST("the example")
{
    InputMap in; in.bind(32, JUMP); in.bind(87, JUMP);
    in.update({ 32 }); CHECK(in.pressed(JUMP)); CHECK(in.held(JUMP)); CHECK(!in.released(JUMP));
    in.update({ 32, 87 }); CHECK(!in.pressed(JUMP)); CHECK(in.held(JUMP));
    in.update({}); CHECK(in.released(JUMP)); CHECK(!in.held(JUMP)); CHECK(!in.pressed(JUMP));
    in.update({}); CHECK(!in.released(JUMP));
}
TEST("switching keys is not a new press") { InputMap in; in.bind(65, LEFT); in.bind(37, LEFT); in.update({ 65 }); in.update({ 37 }); CHECK(!in.pressed(LEFT)); CHECK(in.held(LEFT)); }
TEST("one key, two actions") { InputMap in; in.bind(17, FIRE); in.bind(17, JUMP); in.update({ 17 }); CHECK(in.pressed(FIRE)); CHECK(in.pressed(JUMP)); }
TEST("unbound keys do nothing") { InputMap in; in.bind(32, JUMP); in.update({ 99 }); CHECK(!in.held(JUMP)); }
TEST("before any update") { InputMap in; in.bind(32, JUMP); CHECK(!in.held(JUMP)); CHECK(!in.pressed(JUMP)); CHECK(!in.released(JUMP)); }
TEST("press again after release") { InputMap in; in.bind(32, JUMP); in.update({ 32 }); in.update({}); in.update({ 32 }); CHECK(in.pressed(JUMP)); }

